652:int parse_msg(char* const buf, const unsigned int len, struct sip_msg* const msg)
   660
   661          /* eat crlf & whitespaces from the beginning */
   662          for (tmp=buf; (tmp-buf < len)
   663                          && (*tmp=='\n' || *tmp=='\r' || *tmp=='\0'
   664                                  || *tmp=='\t' || *tmp==' ');
   665                          tmp++);
   666          offset=tmp-buf;
   667          fl=&(msg->first_line);
   668          rest=parse_first_line(tmp, len-offset, fl);
   669          offset+=rest-tmp;
   670          tmp=rest;
   671          switch(fl->type){
   672                  case SIP_INVALID:
   673                          DBG("invalid message\n");
   674                          goto error;
   675                          break;
   676                  case SIP_REQUEST:
   677                          DBG("SIP Request:\n");
   678                          DBG(" method:  <%.*s>\n", fl->u.request.method.len,
   679                                          ZSW(fl->u.request.method.s));
   680                          DBG(" uri:     <%.*s>\n", fl->u.request.uri.len,
   681                                          ZSW(fl->u.request.uri.s));
   682                          DBG(" version: <%.*s>\n", fl->u.request.version.len,
   683                                          ZSW(fl->u.request.version.s));
   684                          flags=HDR_VIA_F;
   685                          break;
   686                  case SIP_REPLY:
   687                          DBG("SIP Reply  (status):\n");
   688                          DBG(" version: <%.*s>\n", fl->u.reply.version.len,
   689                                          ZSW(fl->u.reply.version.s));
   690                          DBG(" status:  <%.*s>\n", fl->u.reply.status.len,
   691                                          ZSW(fl->u.reply.status.s));
   692                          DBG(" reason:  <%.*s>\n", fl->u.reply.reason.len,
   693                                          ZSW(fl->u.reply.reason.s));
   694                          /* flags=HDR_VIA | HDR_VIA2; */
   695                          /* we don't try to parse VIA2 for local messages; -Jiri */
   696                          flags=HDR_VIA_F;
   697                          break;
   698                  default:
   699                          DBG("unknown type %d\n", fl->type);
   700                          goto error;
   701          }
   702          msg->unparsed=tmp;
   703          /*find first Via: */
   704          if (parse_headers(msg, flags, 0)==-1) goto error;
   705
   706  #ifdef EXTRA_DEBUG
   707          /* dump parsed data */
   708          if (msg->via1){
   709                  DBG("first via: <%.*s/%.*s/%.*s> <%.*s:%.*s(%d)>",
   710                                  msg->via1->name.len, ZSW(msg->via1->name.s),
   711                                  msg->via1->version.len, ZSW(msg->via1->version.s),
   712                                  msg->via1->transport.len, ZSW(msg->via1->transport.s),
   713                                  msg->via1->host.len, ZSW(msg->via1->host.s),
   714                                  msg->via1->port_str.len, ZSW(msg->via1->port_str.s),
   715                                  msg->via1->port);
   716                  if (msg->via1->params.s)
   717                          DBG(";<%.*s>", msg->via1->params.len, ZSW(msg->via1->params.s));
   718                  if (msg->via1->comment.s)
   719                          DBG(" <%.*s>", msg->via1->comment.len, ZSW(msg->via1->comment.s));
   720                  DBG ("\n");
   721          }
   722          if (msg->via2){
   723                  DBG("second via: <%.*s/%.*s/%.*s> <%.*s:%.*s(%d)>",
   724                                  msg->via2->name.len, ZSW(msg->via2->name.s),
   725                                  msg->via2->version.len, ZSW(msg->via2->version.s),
   726                                  msg->via2->transport.len, ZSW(msg->via2->transport.s),
   727                                  msg->via2->host.len, ZSW(msg->via2->host.s),
   728                                  msg->via2->port_str.len, ZSW(msg->via2->port_str.s),
   729                                  msg->via2->port);
   730                  if (msg->via2->params.s)
   731                          DBG(";<%.*s>", msg->via2->params.len, ZSW(msg->via2->params.s));
   732                  if (msg->via2->comment.s)
   733                          DBG(" <%.*s>", msg->via2->comment.len, ZSW(msg->via2->comment.s));
   734                  DBG ("\n");
   735          }
   736  #endif
   737
   738
   739  #ifdef EXTRA_DEBUG
   740          DBG("exiting parse_msg\n");
   741  #endif
   742
   743          return 0;
   744
   745  error:
   746          /* more debugging, msg->orig is/should be null terminated*/
   747          LOG(cfg_get(core, core_cfg, sip_parser_log), "ERROR: parse_msg: message=<%.*s>\n",
   748                          (int)msg->len, ZSW(msg->buf));
   749          return -1;
   750  }
