   754  void free_reply_lump( struct lump_rpl *lump)
   755  {
   756          struct lump_rpl *foo, *bar;
   757          for(foo=lump;foo;)
   758          {
   759                  bar=foo->next;
   760                  free_lump_rpl(foo);
   761                  foo = bar;
   762          }
