   766  /*only the content*/
   767  void free_sip_msg(struct sip_msg* const msg)
   768  {
   769          reset_new_uri(msg);
   770          reset_dst_uri(msg);
   771          reset_path_vector(msg);
   772          reset_instance(msg);
   773          reset_ruid(msg);
   774          reset_ua(msg);
   775          if (msg->headers)     free_hdr_field_lst(msg->headers);
   776          if (msg->body && msg->body->free) msg->body->free(&msg->body);
   777          if (msg->add_rm)      free_lump_list(msg->add_rm);
   778          if (msg->body_lumps)  free_lump_list(msg->body_lumps);
   779          if (msg->reply_lump)   free_reply_lump(msg->reply_lump);
   780          msg_ldata_reset(msg);
